import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';

import { PlanService } from '../../services/plan.service';
import { Alumno } from '../../models/alumno.model';
import { Materia } from '../../models/materia.model';
import { Estadisticas, Alerta, OpcionEstrategia, Recomendacion, TipoEstrategia } from '../../models/plan.model';

import { SidebarComponent } from '../sidebar/sidebar.component';
import { MateriasDisponiblesComponent } from '../materias-disponibles/materias-disponibles.component';
import { SimulacionCarreraComponent } from '../simulacion-carrera/simulacion-carrera.component';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, SidebarComponent, MateriasDisponiblesComponent, SimulacionCarreraComponent],
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css'],
})
export class DashboardComponent implements OnInit {
  alumno: Alumno | null = null;
  materias: Materia[] = [];
  estadisticas: Estadisticas | null = null;
  alertas: Alerta[] = [];
  opcionesEstrategia: OpcionEstrategia[] = [];
  recomendacion: Recomendacion | null = null;

  estrategiaSeleccionada: TipoEstrategia = 'rapida';
  loadingSimulacion = false;
  exportando = false;

  constructor(private planService: PlanService) {}

  ngOnInit(): void {
    const legajo = '123456'; // En un caso real vendría de auth/sesión

    this.planService.getAlumno(legajo).subscribe(alumno => (this.alumno = alumno));
    this.planService.getMateriasDisponibles(legajo).subscribe(materias => (this.materias = materias));
    this.planService.getAlertas(legajo).subscribe(alertas => (this.alertas = alertas));
    this.planService.getOpcionesEstrategia().subscribe(opciones => (this.opcionesEstrategia = opciones));

    this.cargarEstadisticas(legajo);
    this.simular(legajo, this.estrategiaSeleccionada);
  }

  private cargarEstadisticas(legajo: string): void {
    this.planService.getEstadisticas(legajo, this.estrategiaSeleccionada).subscribe(stats => (this.estadisticas = stats));
  }

  onSeleccionarEstrategia(tipo: TipoEstrategia): void {
    this.estrategiaSeleccionada = tipo;
    const legajo = this.alumno?.legajo ?? '123456';
    this.cargarEstadisticas(legajo);
    this.simular(legajo, tipo);
  }

  private simular(legajo: string, tipo: TipoEstrategia): void {
    this.loadingSimulacion = true;
    this.planService.simularCarrera(legajo, tipo).subscribe(rec => {
      this.recomendacion = rec;
      this.loadingSimulacion = false;
    });
  }

  exportarPDF(): void {
    const legajo = this.alumno?.legajo ?? '123456';
    this.exportando = true;
    this.planService.exportarPDF(legajo).subscribe(() => {
      this.exportando = false;
      console.log('PDF exportado (mock)');
    });
  }

  generarSimulacion(): void {
    const legajo = this.alumno?.legajo ?? '123456';
    this.simular(legajo, this.estrategiaSeleccionada);
  }
}
<div class="layout">
  <app-sidebar [alumno]="alumno" [estadisticas]="estadisticas"></app-sidebar>

  <main class="main">
    <section class="card panel-header">
      <div>
        <p class="eyebrow">Panel principal</p>
        <h1>Bienvenido, {{ alumno ? alumno.getNombre() : '...' }}</h1>
        <p class="desc">
          Revisión rápida del progreso académico, materias disponibles, alertas y simulación de cursada.
        </p>
      </div>
      <div class="actions">
        <button class="btn-secondary" (click)="exportarPDF()" [disabled]="exportando">
          <i class="ti ti-download"></i>
          {{ exportando ? 'Exportando...' : 'Exportar PDF' }}
        </button>
        <button class="btn-primary" (click)="generarSimulacion()" [disabled]="loadingSimulacion">
          <i class="ti ti-sparkles"></i>
          Generar simulación
        </button>
      </div>
    </section>

    <section class="metrics" *ngIf="estadisticas as e">
      <div class="metric-card">
        <div class="metric-top">
          <p class="metric-label">Promedio general</p>
          <span class="metric-icon"><i class="ti ti-trending-up"></i></span>
        </div>
        <p class="metric-value">{{ e.promedio }}</p>
        <p class="metric-foot">Promedio acumulado</p>
      </div>

      <div class="metric-card">
        <div class="metric-top">
          <p class="metric-label">Materias aprobadas</p>
          <span class="metric-icon"><i class="ti ti-circle-check"></i></span>
        </div>
        <p class="metric-value">{{ e.aprobadas }}</p>
        <p class="metric-foot">de {{ e.totalMaterias }} totales</p>
      </div>

      <div class="metric-card">
        <div class="metric-top">
          <p class="metric-label">Egreso estimado</p>
          <span class="metric-icon"><i class="ti ti-calendar"></i></span>
        </div>
        <p class="metric-value metric-value-sm">{{ e.fechaEgresoEstimada | date: 'MMMM yyyy' }}</p>
        <p class="metric-foot">Estrategia: {{ e.estrategia === 'rapida' ? 'Cursada rápida' : e.estrategia === 'minima' ? 'Cursada mínima' : 'Materias por año' }}</p>
      </div>

      <div class="metric-card">
        <div class="metric-top">
          <p class="metric-label">Alertas activas</p>
          <span class="metric-icon"><i class="ti ti-bell"></i></span>
        </div>
        <p class="metric-value">{{ alertas.length }}</p>
        <p class="metric-foot">Revisar antes de inscribirte</p>
      </div>
    </section>

    <section class="content-grid">
      <app-materias-disponibles [materias]="materias"></app-materias-disponibles>

      <app-simulacion-carrera
        [opciones]="opcionesEstrategia"
        [seleccionada]="estrategiaSeleccionada"
        [recomendacion]="recomendacion"
        [loading]="loadingSimulacion"
        (seleccionar)="onSeleccionarEstrategia($event)"
      ></app-simulacion-carrera>
    </section>

    <section class="card" *ngIf="alertas.length">
      <h2><i class="ti ti-bell"></i> Alertas</h2>
      <div class="alertas">
        <div class="alerta" *ngFor="let alerta of alertas" [ngClass]="'alerta-' + alerta.tipo">
          <i class="ti" [ngClass]="{
            'ti-alert-triangle': alerta.tipo === 'warning',
            'ti-alert-circle': alerta.tipo === 'danger',
            'ti-info-circle': alerta.tipo === 'info'
          }"></i>
          <div>
            <p class="alerta-titulo">{{ alerta.titulo }}</p>
            <p class="alerta-mensaje">{{ alerta.mensaje }}</p>
          </div>
        </div>
      </div>
    </section>
  </main>
</div>
